/**
 * VOD Playback Worker
 *
 * Implements the place.stream.playback XRPC API backed by an S3 bucket
 * containing MUXL archives and HLS metadata generated by `muxl hls`.
 *
 * S3 bucket layout:
 *   blobs/{cid}              - raw MUXL archive bytes
 *   {did}/{rkey}/metadata.json - track/segment metadata from `muxl hls`
 *   {did}/{rkey}/init-{track}.mp4 - per-track init segments
 */

interface Env {
  S3_BUCKET_URL: string;
}

interface TrackSegment {
  offset: number;
  size: number;
  durationTicks: number;
  sampleCount: number;
}

interface TrackMeta {
  type: "video" | "audio";
  codec: string;
  timescale: number;
  initCid: string;
  segments: TrackSegment[];
  // video
  width?: number;
  height?: number;
  // audio
  channels?: number;
  sampleRate?: number;
}

interface VideoMeta {
  blobCid: string;
  blobSize: number;
  tracks: Record<string, TrackMeta>;
}

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, HEAD, OPTIONS",
  "Access-Control-Allow-Headers": "Range",
  "Access-Control-Expose-Headers": "Content-Length, Content-Range",
};

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    if (request.method === "OPTIONS") {
      return new Response(null, { headers: CORS_HEADERS });
    }

    const url = new URL(request.url);
    const path = url.pathname;

    try {
      if (path === "/xrpc/place.stream.playback.getVideoPlaylist") {
        return await handleGetVideoPlaylist(url, env);
      }
      if (path === "/xrpc/place.stream.playback.getInitSegment") {
        return await handleGetInitSegment(url, env);
      }
      if (path === "/xrpc/place.stream.playback.getVideoBlob") {
        return await handleGetVideoBlob(url, request, env);
      }
      return new Response("Not Found", { status: 404 });
    } catch (e: any) {
      if (e instanceof XRPCError) {
        return json({ error: e.name, message: e.message }, e.status);
      }
      return new Response(e.message || "Internal Server Error", {
        status: 500,
      });
    }
  },
};

class XRPCError extends Error {
  constructor(
    public status: number,
    public override name: string,
    message: string
  ) {
    super(message);
  }
}

function json(data: any, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "Content-Type": "application/json", ...CORS_HEADERS },
  });
}

// ---------------------------------------------------------------------------
// Metadata cache (per-isolate, short TTL)
// ---------------------------------------------------------------------------

const metaCache = new Map<string, { meta: VideoMeta; expires: number }>();

async function fetchMeta(
  did: string,
  rkey: string,
  env: Env
): Promise<VideoMeta> {
  const key = `${did}/${rkey}`;
  const cached = metaCache.get(key);
  if (cached && cached.expires > Date.now()) {
    return cached.meta;
  }

  const didDir = did.replace(/:/g, "-");
  const resp = await fetch(
    `${env.S3_BUCKET_URL}/${didDir}/${rkey}/metadata.json`
  );
  if (!resp.ok) {
    throw new XRPCError(
      404,
      "VideoNotFound",
      `No video found for ${did} ${rkey}`
    );
  }
  const meta: VideoMeta = await resp.json();
  metaCache.set(key, { meta, expires: Date.now() + 60_000 });
  return meta;
}

// ---------------------------------------------------------------------------
// place.stream.playback.getVideoPlaylist
// ---------------------------------------------------------------------------

async function handleGetVideoPlaylist(
  url: URL,
  env: Env
): Promise<Response> {
  const did = url.searchParams.get("did");
  const rkey = url.searchParams.get("rkey");
  if (!did || !rkey) {
    throw new XRPCError(400, "InvalidRequest", "did and rkey are required");
  }

  const track = url.searchParams.get("track");
  const meta = await fetchMeta(did, rkey, env);

  const playlist = track
    ? mediaPlaylist(meta, track, did, rkey)
    : masterPlaylist(meta, did, rkey);

  return new Response(playlist, {
    headers: {
      "Content-Type": "application/vnd.apple.mpegurl",
      ...CORS_HEADERS,
    },
  });
}

function masterPlaylist(
  meta: VideoMeta,
  did: string,
  rkey: string
): string {
  const lines: string[] = ["#EXTM3U", "#EXT-X-VERSION:6", ""];

  for (const [tid, t] of Object.entries(meta.tracks)) {
    if (t.type === "audio") {
      const uri = xrpcURL("place.stream.playback.getVideoPlaylist", {
        did,
        rkey,
        track: tid,
      });
      lines.push(
        `#EXT-X-MEDIA:TYPE=AUDIO,GROUP-ID="audio",NAME="audio${tid}",` +
          `DEFAULT=YES,AUTOSELECT=YES,CHANNELS="${t.channels ?? 2}",URI="${uri}"`
      );
    }
  }
  lines.push("");

  // Collect audio codec for CODECS string
  const audioCodec = Object.values(meta.tracks).find(
    (t) => t.type === "audio"
  )?.codec;

  for (const [tid, t] of Object.entries(meta.tracks)) {
    if (t.type === "video") {
      const totalBytes = t.segments.reduce((s, seg) => s + seg.size, 0);
      const totalTicks = t.segments.reduce(
        (s, seg) => s + seg.durationTicks,
        0
      );
      const totalSamples = t.segments.reduce(
        (s, seg) => s + seg.sampleCount,
        0
      );
      const totalDur = totalTicks / t.timescale;
      const bandwidth = totalDur > 0 ? Math.round((totalBytes * 8) / totalDur) : 0;
      const frameRate = totalDur > 0 ? totalSamples / totalDur : 0;
      const codecs = audioCodec ? `${t.codec},${audioCodec}` : t.codec;

      const uri = xrpcURL("place.stream.playback.getVideoPlaylist", {
        did,
        rkey,
        track: tid,
      });
      lines.push(
        `#EXT-X-STREAM-INF:AUDIO="audio",BANDWIDTH=${bandwidth},` +
          `CODECS="${codecs}",RESOLUTION=${t.width}x${t.height},` +
          `FRAME-RATE=${frameRate.toFixed(3)}`
      );
      lines.push(uri);
    }
  }

  return lines.join("\n") + "\n";
}

function mediaPlaylist(
  meta: VideoMeta,
  trackId: string,
  did: string,
  rkey: string
): string {
  const t = meta.tracks[trackId];
  if (!t) {
    throw new XRPCError(404, "TrackNotFound", `Track ${trackId} not found`);
  }

  const maxDurSec = t.segments.reduce(
    (m, seg) => Math.max(m, seg.durationTicks / t.timescale),
    0
  );
  const targetDuration = Math.max(1, Math.ceil(maxDurSec));

  const initURI = xrpcURL("place.stream.playback.getInitSegment", {
    did,
    rkey,
    track: trackId,
  });

  const lines: string[] = [
    "#EXTM3U",
    "#EXT-X-VERSION:6",
    "#EXT-X-PLAYLIST-TYPE:VOD",
    "#EXT-X-INDEPENDENT-SEGMENTS",
    `#EXT-X-TARGETDURATION:${targetDuration}`,
    "#EXT-X-MEDIA-SEQUENCE:0",
    `#EXT-X-MAP:URI="${initURI}"`,
    "",
  ];

  for (const seg of t.segments) {
    const durSec = seg.durationTicks / t.timescale;
    // Encode byte range in the CID parameter so getVideoBlob can serve it
    const segRef = `${meta.blobCid}:${seg.offset}:${seg.size}`;
    const uri =
      xrpcURL("place.stream.playback.getVideoBlob", {
        did,
        rkey,
        cid: segRef,
      }) + ".m4s";
    lines.push(`#EXTINF:${durSec.toFixed(6)},`);
    lines.push(uri);
  }

  lines.push("#EXT-X-ENDLIST");
  return lines.join("\n") + "\n";
}

// ---------------------------------------------------------------------------
// place.stream.playback.getInitSegment
// ---------------------------------------------------------------------------

async function handleGetInitSegment(
  url: URL,
  env: Env
): Promise<Response> {
  const did = url.searchParams.get("did");
  const rkey = url.searchParams.get("rkey");
  const track = url.searchParams.get("track");
  if (!did || !rkey || !track) {
    throw new XRPCError(
      400,
      "InvalidRequest",
      "did, rkey, and track are required"
    );
  }

  const meta = await fetchMeta(did, rkey, env);
  const t = meta.tracks[track];
  if (!t) {
    throw new XRPCError(404, "TrackNotFound", `Track ${track} not found`);
  }

  // Fetch init segment from S3 by its CID in the blobs directory
  const resp = await fetch(`${env.S3_BUCKET_URL}/blobs/${t.initCid}.mp4`);
  if (!resp.ok) {
    throw new XRPCError(404, "TrackNotFound", "Init segment not available");
  }

  return new Response(resp.body, {
    headers: {
      "Content-Type": "video/mp4",
      "Cache-Control": "public, max-age=31536000, immutable",
      ...CORS_HEADERS,
    },
  });
}

// ---------------------------------------------------------------------------
// place.stream.playback.getVideoBlob
// ---------------------------------------------------------------------------

async function handleGetVideoBlob(
  url: URL,
  request: Request,
  env: Env
): Promise<Response> {
  const did = url.searchParams.get("did");
  const rkey = url.searchParams.get("rkey");
  if (!did || !rkey) {
    throw new XRPCError(400, "InvalidRequest", "did and rkey are required");
  }

  let cidParam = url.searchParams.get("cid") ?? "";
  // Strip .m4s suffix appended for HLS player file extension sniffing
  cidParam = cidParam.replace(/\.m4s$/, "");

  // CID can be "blobCid:offset:size" for byte-range segments
  const parts = cidParam.split(":");
  const blobCid = parts[0];

  const headers: Record<string, string> = {};
  if (parts.length === 3) {
    // Encoded byte range from playlist
    const offset = parseInt(parts[1], 10);
    const size = parseInt(parts[2], 10);
    headers["Range"] = `bytes=${offset}-${offset + size - 1}`;
  } else {
    // Pass through client Range header if present
    const range = request.headers.get("Range");
    if (range) {
      headers["Range"] = range;
    }
  }

  const resp = await fetch(`${env.S3_BUCKET_URL}/blobs/${blobCid}.mp4`, {
    headers,
  });

  if (!resp.ok && resp.status !== 206) {
    throw new XRPCError(404, "BlobNotFound", "Blob not available");
  }

  const responseHeaders: Record<string, string> = {
    "Content-Type": "video/mp4",
    "Cache-Control": "public, max-age=31536000, immutable",
    ...CORS_HEADERS,
  };

  // Forward content-range for byte-range responses
  const contentRange = resp.headers.get("Content-Range");
  if (contentRange) {
    responseHeaders["Content-Range"] = contentRange;
  }
  const contentLength = resp.headers.get("Content-Length");
  if (contentLength) {
    responseHeaders["Content-Length"] = contentLength;
  }

  return new Response(resp.body, {
    status: resp.status,
    headers: responseHeaders,
  });
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function xrpcURL(method: string, params: Record<string, string>): string {
  const qs = Object.entries(params)
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
    .join("&");
  return `${method}?${qs}`;
}
